/* vNN.xx, UI REDESIGN ui5q2r (his #50, from the AAA judge of the title shot): FULLSCREEN IS A FOOTER PROMPT. BEST IN FULLSCREEN AT
   1080p, 1440p OR 4K and GO FULLSCREEN sat in the middle of the column under the name, a line of setup text in the place a title
   keeps for itself. They are a small prompt in the bottom left corner of the screen now; the words and the button are the same. */
#root #titleres{ position:absolute; left:28px; bottom:22px; margin:0 !important; justify-content:flex-start !important; gap:10px !important;
  font-size:13px !important; color:var(--tx-3, #8a96a1) !important; z-index:2; }
#root #titleres #titlefs{ min-height:32px; }
/* vNN.xx, UI REDESIGN ui5q1c (his #50, from the AAA judge

check:
{v:'VER',what:'his #50 (UI redesign ui5q2r): BEST IN FULLSCREEN and GO FULLSCREEN are a prompt in the bottom left corner of the title, not a line in the middle of the column',
 run:function(){
   var ti=document.getElementById('title'), r=document.getElementById('titleres'); if(!ti||!r) return 'SKIP: no fullscreen line';
   var was=ti.classList.contains('on');
   try{
     if(!was) ti.classList.add('on');
     if(getComputedStyle(r).position!=='absolute') return 'the fullscreen line is in the column flow';
     var tb=ti.getBoundingClientRect(), rb=r.getBoundingClientRect();
     if(tb.bottom-rb.bottom>80*((parseFloat(ti.style.zoom)||1))) return 'the fullscreen prompt is not at the foot of the screen ('+Math.round(tb.bottom-rb.bottom)+'px up)';
     if(rb.left-tb.left>80) return 'the fullscreen prompt is not in the left corner';
     return null;
   } finally { if(!was) ti.classList.remove('on'); } }},
